import{_ as t,o as e,c as r,a5 as i}from"./chunks/framework.QWVCgkrI.js";const u=JSON.parse('{"title":"TAAを切り替えて床のちらつきとゴーストを比べる","description":"","frontmatter":{"title":"TAAを切り替えて床のちらつきとゴーストを比べる","study":{"source":"新規執筆","section":"practice","format":"sample","status":"published","domain":"graphics","collection":"taa-observation","order":1,"summary":"カメラと物体を別々に動かし、TAAで床のちらつきが弱まる場面と、異なる面の履歴が残像になる場面を観察する。","aliases":["TAAの実践","WebGL 2","時間的アンチエイリアシング","再投影","履歴検証","ディスオクルージョン","ゴースティング"],"verification":"Yang・Liu・Salviの論文とKarisのSIGGRAPH講演に照合（2026-11-13）"}},"headers":[],"relativePath":"practice/graphics/taa-observation.md","filePath":"practice/graphics/taa-observation.md"}'),s={name:"practice/graphics/taa-observation.md"};function l(o,a,n,h,d,c){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="taaを切り替えて床のちらつきとゴーストを比べる" tabindex="-1">TAAを切り替えて床のちらつきとゴーストを比べる <a class="header-anchor" href="#taaを切り替えて床のちらつきとゴーストを比べる" aria-label="Permalink to &quot;TAAを切り替えて床のちらつきとゴーストを比べる&quot;">​</a></h1><p>市松模様の床と黄色い物体を描きます。カメラだけを動かして床のちらつきを、物体だけを動かしてその後ろの床に出るゴーストを比べます。<a href="/study/graphics/postprocess/taa.html">TAAの記事</a>で、どの色を履歴から読むかを図解しています。</p><p><a href="/study/samples/graphics/taa-observation/index.html" target="_self">TAAの比較デモを開く</a></p><h2 id="カメラを動かして床を比べる" tabindex="-1">カメラを動かして床を比べる <a class="header-anchor" href="#カメラを動かして床を比べる" aria-label="Permalink to &quot;カメラを動かして床を比べる&quot;">​</a></h2><ol><li><strong>カメラを横に動かす</strong>をオンにします。<strong>物体を横に動かす</strong>はオフにします。</li><li>TAAオフで、黄色い物体から離れた床の奥を見ます。カメラの横移動に合わせて、模様が細かく明滅します。</li><li><strong>TAAをオンにする</strong>を選び、数フレーム分の履歴がたまるまで少し待ちます。同じ場所を見て、模様の明滅がどれだけ弱くなるか比べます。</li></ol><p>描画解像度と床のポイントサンプリングは共通です。TAAをオンにすると、サンプル位置をわずかにずらし、床の同じ位置を過去のカメラへ再投影した結果を混ぜます。<a href="/study/practice/graphics/texture-filtering-observation.html">フィルタリングの実践</a>では、テクスチャから読む範囲を変える方法も試せます。</p><h2 id="物体を動かしてゴーストを比べる" tabindex="-1">物体を動かしてゴーストを比べる <a class="header-anchor" href="#物体を動かしてゴーストを比べる" aria-label="Permalink to &quot;物体を動かしてゴーストを比べる&quot;">​</a></h2><ol><li>カメラの移動を止め、<strong>物体を横に動かす</strong>をオンにします。TAAをオフにして、黄色い物体が通った直後の床を見ます。</li><li>TAAをオンにし、<strong>異なる面の履歴を捨てる</strong>をオフにします。動く物体の後ろに黄色が薄く残る場所を探します。</li><li><strong>異なる面の履歴を捨てる</strong>をオンにします。床の上に残っていた黄色がどう変わるか、同じ移動で見比べます。</li></ol><p>ゴーストの観察用に、初期設定では、画面内の再投影先に異なる面の色があっても混ぜます。面の検証を有効にすると、床、物体、背景の区別を使い、前後で面が一致しない場所の履歴を捨てます。履歴色を周囲の画素から補間するため、輪郭付近には色が少し残る場合があります。</p><p><strong>履歴を消す</strong>を押すと、カメラと物体の位置を保ったまま、蓄積をやり直せます。TAAをオンにした状態で試すと、現在のサンプルから始まり、フレームが進むにつれて見え方が落ち着く様子を観察できます。</p><h2 id="webgl-2で履歴を保存する" tabindex="-1">WebGL 2で履歴を保存する <a class="header-anchor" href="#webgl-2で履歴を保存する" aria-label="Permalink to &quot;WebGL 2で履歴を保存する&quot;">​</a></h2><table tabindex="0"><thead><tr><th>設定</th><th>現在のフレーム</th><th>画面に出す色</th></tr></thead><tbody><tr><td>TAAオフ</td><td>基準のサンプル位置で描く</td><td>現在色</td></tr><tr><td>TAAオン</td><td>ジッタを加えた位置で描く</td><td>履歴を使える画素は現在10%・履歴90%。履歴を使えない画素は現在色</td></tr></tbody></table><p>履歴画像を2枚用意します。1枚から前フレームまでの蓄積結果を読み、もう1枚に今回の結果を書きます。次のフレームでは2枚の役割を入れ替えます。背景の床はカメラの動きで、黄色い物体はカメラと物体の両方の動きで再投影します。<a href="/study/graphics/postprocess/ping-pong-and-history.html">ピンポンと履歴バッファ</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>TAAをオンにすると、遠くの床の色は何を使って決まりますか。</p><details class="details custom-block"><summary>解答</summary><p>ジッタを加えた位置で取った現在色と、同じ面を前フレームへ再投影した先の履歴色です。使える履歴を混ぜると、1フレームだけの色の変化が弱まります。</p></details></li><li><p>物体が通った後の床で、履歴から黄色が見つかるのはなぜですか。</p><details class="details custom-block"><summary>解答</summary><p>前フレームの同じ場所では物体が床を覆っていました。再投影した画面座標には、現在見えている床の色の代わりに、当時見えていた物体の色が保存されています。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/graphics/postprocess/taa.html">TAA</a>でジッタ、再投影、履歴検証の関係を整理する。</li><li><a href="/study/practice/graphics/msaa-observation.html">MSAAの実践</a>で、同じフレームの複数サンプルが輪郭にどう効くかを確認する。</li><li><a href="/study/learn/roadmap.html?node=gfx-postprocess#graphics">3DCG・描画ロードマップの「ポストプロセスとAA」</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://diglib.eg.org/items/cfa6a05c-53b3-4ee1-979d-48abc6225f6b" target="_blank" rel="noreferrer">Lei Yang, Shiqiu Liu, Marco Salvi — A Survey of Temporal Antialiasing Techniques</a></li><li><a href="https://de45xmedrsdbp.cloudfront.net/Resources/files/TemporalAA_small-59732822.pdf" target="_blank" rel="noreferrer">Brian Karis — High Quality Temporal Supersampling</a></li></ul>',19)])])}const m=t(s,[["render",l]]);export{u as __pageData,m as default};
